  "lines": [
    {
      "id": "progress.weight_pr",
      "tiers": [
        {
          "id": "progress.weight_pr:t1",
          "title": "Первый рейс железа",
          "phrase": "У тебя первый день рекорда: рабочий вес в выполненном сопоставимом подходе вырос. Блины тихонько вызвали погрузчик.",
          "imagePrompt": "A compact forklift with expressive headlights eases its forks beneath a single upright weight plate, leaning forward with careful curiosity; a short barbell rests on a low loading stand beside it.",
          "fishMarkup": "[warm] У тебя первый день рекорда: рабочий вес в выполненном сопоставимом подходе вырос. Блины <soft>тихонько вызвали погрузчик.</soft>",
          "audioText": "У тебя первый день рекорда: рабочий вес в выполненном сопоставимом подходе вырос. Блины тихонько вызвали погрузчик."
        },
        {
          "id": "progress.weight_pr:t2",
          "title": "Блинная логистика",
          "phrase": "В твоей истории — 3 дня рекорда рабочего веса в выполненных сопоставимых подходах. Блины завели отдел логистики.",
          "imagePrompt": "The compact forklift carries a neatly secured stack of weight plates up a short loading ramp toward a waiting barbell; its forks hover above an unloading stand, with coiled lifting straps ready beside it.",
          "fishMarkup": "[confident] В твоей истории — <emphasis>3 дня рекорда рабочего веса</emphasis> в выполненных сопоставимых подходах. [playful] Блины завели отдел логистики.",
          "audioText": "В твоей истории — 3 дня рекорда рабочего веса в выполненных сопоставимых подходах. Блины завели отдел логистики."
        },
        {
          "id": "progress.weight_pr:t3",
          "title": "Погрузчик для погрузчика",
          "phrase": "Ты накопил 8 дней рекорда рабочего веса в выполненных сопоставимых подходах. Погрузчику для блинов понадобился свой погрузчик.",
          "imagePrompt": "The compact forklift proudly holds a stack of weight plates while riding on the raised forks of a much larger forklift; both vehicles lean forward in matching poses, turning a routine plate delivery into an absurd nested convoy.",
          "fishMarkup": "[triumphant] Ты накопил <emphasis>8 дней рекорда рабочего веса</emphasis> в выполненных сопоставимых подходах. Погрузчику для блинов понадобился <slow>свой погрузчик.</slow>",
          "audioText": "Ты накопил 8 дней рекорда рабочего веса в выполненных сопоставимых подходах. Погрузчику для блинов понадобился свой погрузчик."
        }
      ]
    },
    {
      "id": "progress.estimate_pr",
      "tiers": [
        {
          "id": "progress.estimate_pr:t1",
          "title": "Костяшки разминаются",
          "phrase": "Твой первый день расчётного рекорда: оценочный показатель силы вырос больше чем на 1%. Счёты довольно потёрли костяшки.",
          "imagePrompt": "A small abacus with mitten hands and stubby feet slides a single bead along its lowest rod as if testing a piano key; the other hand hovers expectantly, and one foot reaches toward a tiny practice pedal.",
          "fishMarkup": "[warm] Твой первый день расчётного рекорда: оценочный показатель силы вырос больше чем на 1%. [playful] Счёты довольно потёрли костяшки.",
          "audioText": "Твой первый день расчётного рекорда: оценочный показатель силы вырос больше чем на 1%. Счёты довольно потёрли костяшки."
        },
        {
          "id": "progress.estimate_pr:t2",
          "title": "Расчёт набрал темп",
          "phrase": "У тебя уже 3 дня расчётного рекорда: оценочный показатель силы в каждый из них вырос больше чем на 1%. Счёты играют всё увереннее.",
          "imagePrompt": "The little abacus balances on a piano stool and plays its own bead rows with both mitten hands; several beads bunch into rhythmic clusters while a stubby foot presses a wooden pedal beneath the frame.",
          "fishMarkup": "[confident] У тебя уже <emphasis>3 дня расчётного рекорда</emphasis>: оценочный показатель силы в каждый из них вырос больше чем на 1%. Счёты играют всё увереннее.",
          "audioText": "У тебя уже 3 дня расчётного рекорда: оценочный показатель силы в каждый из них вырос больше чем на 1%. Счёты играют всё увереннее."
        },
        {
          "id": "progress.estimate_pr:t3",
          "title": "Костяшки на бис",
          "phrase": "Ты собрал 8 дней расчётного рекорда: оценочный показатель силы каждый раз рос больше чем на 1%. Счёты дали концерт и сами себе заказали бис.",
          "imagePrompt": "The lively abacus has unfolded its own frame into a concert grand piano, with bead-covered rods serving as keys; its mitten hands strike a final chord while several beads leap into the open lid like cheering spectators.",
          "fishMarkup": "[triumphant] Ты собрал <emphasis>8 дней расчётного рекорда</emphasis>: оценочный показатель силы каждый раз рос больше чем на 1%. Счёты дали концерт и <slow>сами себе заказали бис.</slow>",
          "audioText": "Ты собрал 8 дней расчётного рекорда: оценочный показатель силы каждый раз рос больше чем на 1%. Счёты дали концерт и сами себе заказали бис."
        }
      ]
    }
  ]
}
